class Solution:
 def makeFancyString(self,s):
  out=[]
  for c in s:
   if len(out)<2 or not(out[-1]==out[-2]==c):out.append(c)
  return ''.join(out)

class Solution:
 def isPrefixString(self,s,words):
  out=''
  for w in words:
   out+=w
   if out==s:return True
   if len(out)>=len(s):return False
  return False

class Solution:
 def validPath(self,n,edges,source,destination):
  g=[[] for _ in range(n)]
  for a,b in edges:g[a].append(b);g[b].append(a)
  seen={source};stack=[source]
  while stack:
   x=stack.pop()
   if x==destination:return True
   for y in g[x]:
    if y not in seen:seen.add(y);stack.append(y)
  return False

class Solution:
 def minTimeToType(self,word):
  pos=0;ans=0
  for c in word:
   nxt=ord(c)-97;d=abs(nxt-pos);ans+=min(d,26-d)+1;pos=nxt
  return ans

import math
class Solution:
 def findGCD(self,nums):return math.gcd(min(nums),max(nums))

class Solution:
 def construct2DArray(self,original,m,n):
  if m*n!=len(original):return []
  return [original[i*n:(i+1)*n] for i in range(m)]

class Solution:
 def twoOutOfThree(self,nums1,nums2,nums3):
  sets=list(map(set,(nums1,nums2,nums3)))
  return sorted(x for x in set.union(*sets) if sum(x in s for s in sets)>=2)
